INSERT INTO `services` VALUES (1,'Pintu UPVC','pintu-upvc','Pintu premium dengan material UPVC kokoh, dilengkapi double-lock system dan tahan cuaca.','DoorClosed','/images/services/pintu-upvc.png',1,'2026-08-03 15:17:26'),(2,'Jendela UPVC','jendela-upvc','Jendela swing, sliding, dan jungkit UPVC kedap suara hingga 40dB dengan desain modern.','Grid','/images/services/jendela-upvc.png',1,'2026-08-03 15:17:26'),(3,'Plafon & Kanopi UPVC','plafon-kanopi-upvc','Solusi kanopi & plafon UPVC anti bocor, tahan panas matahari ekstrem, dan berestetika tinggi.','Layers','/images/services/plafon-kanopi-upvc.png',1,'2026-08-03 15:17:26'),(4,'Kitchen Set UPVC','kitchen-set-upvc','Kitchen set kustom berbahan UPVC premium yang anti air, anti lembab, dan anti rayap 100%.','Utensils','/images/services/kitchen-set-upvc.png',1,'2026-08-03 15:17:26'),(5,'Shower Box','shower-box','Pemasangan shower box kaca tempered dengan kusen UPVC minimalis tahan karat untuk kamar mandi mewah.','ShowerHead','/images/services/shower-box.png',1,'2026-08-03 15:17:26');
